1	export type Item = {
2	  type: string;
3	};
4	
5	export type QuoteStep = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Scenario = {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	};
14	
15	export type ScenarioResults = {
16	  results: unknown[];
17	};
18	
19	const PROCESSING_FEE = 5;
20	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const BLOCK_SIZE = 3;
32	const BLOCK_BASE_PREMIUM = 60;
33	
34	const COMPONENT_TYPES = ["rune", "moonstone"];
35	
36	const countByType = (items: Item[]): Map<string, number> =>
37	  items.reduce(
38	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
39	    new Map<string, number>(),
40	  );
41	
42	/**
43	 * A building block of exactly 3 alike components is offered at a special base
44	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
45	 * runes are charged per item.
46	 */
47	const groupBasePremium = (type: string, count: number): number =>
48	  COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE
49	    ? BLOCK_BASE_PREMIUM
50	    : count * BASE_PREMIUMS[type];
51	
52	const policyBasePremium = (items: Item[]): number =>
53	  [...countByType(items)].reduce((sum, [type, count]) => sum + groupBasePremium(type, count), 0);
54	
55	/** Premiums are rounded in the MHPCO's favour, i.e. up. */
56	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
57	
58	/**
59	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
60	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
61	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
62	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
63	 */
64	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
65	
66	const quote = (step: QuoteStep): { premium: number } => {
67	  const assessedPremium = withSurcharge(
68	    policyBasePremium(step.items),
69	    INITIAL_ASSESSMENT_SURCHARGE,
70	  );
71	
72	  return { premium: roundInMHPCOsFavour(assessedPremium + PROCESSING_FEE) };
73	};
74	
75	export const runScenario = (scenario: Scenario): ScenarioResults => ({
76	  results: scenario.steps.map(quote),
77	});
